INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The sisters are still counting their dead. Come back in %tqt.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901302, 13, 1, NULL, 'BloodPintsOwedWait');
