INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901302, 12, 1, NULL, 'BloodPintsOwedKillTask@KillTaskCompleted');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Five of them. Good. Now the Warden. It stands at the foot of the temple mount. Break it and bring me the stone from its heart, and the font will have nothing left to call with.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901302, 13, 1, NULL, 'BloodPintsOwedKillTask@KillTaskCompleted');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, min, max) VALUES (@e, 0, 30, 0, 1, 'BloodPintsOwedKillTask@KillTaskInProgress', 1, 2147483647);
