INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 18, 0, 1, 'You have freed %tqc of the %tqm sisters Sela Varn asked you to cut down.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901302, 13, 1, NULL, 'BloodPintsOwedKillTask@KillTaskInProgress');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 21, 0, 1, 'BloodFontDrink@BloodPintsOwedKillTask');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901302, 12, 1, NULL, 'BloodFontDrink@BloodPintsOwedKillTask');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'You drank. I can smell it on you. Good: the Warden only wakes for those who owe.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'They drink from that font and call it prayer. I drank from it too, once. Now it wants the rest of me.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'Cut down five of the Blood-Sisters for me, and come back.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, amount) VALUES (@e, 3, 70, 0, 1, 'BloodPintsOwedKillTask', 0);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901302, 13, 1, NULL, 'BloodFontDrink@BloodPintsOwedKillTask');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'They drink from that font and call it prayer. I drank from it too, once. Now it wants the rest of me.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Go to the Blood Font by the lower coven and drink. The Warden only wakes for those who owe. Then come back to me, quickly, before it forgets you.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901302, 6, 1, 901303, NULL);
