INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The Warden''s heart. It is still beating. I will bury it in the sand where the tide can have it.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Take these. The sisters kept a treasury, and I kept the key when I ran.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 31, 0, 1, 'BloodPintsOwedKillTask');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 22, 0, 1, 'BloodPintsOwedWait');
