INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The Gotrok will have a new beast on the picket by morning. Come back in %tqt and we do it again.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901322, 13, 1, NULL, 'GotrokSiegeWait');
