INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901322, 12, 1, NULL, 'GotrokSiegeKillTask@KillTaskCompleted');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Both beasts down. Now the smith himself, the one they call the Siegewright. He carries a charge meant for the gate. Bring it to me.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901322, 13, 1, NULL, 'GotrokSiegeKillTask@KillTaskCompleted');
