INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 18, 0, 1, 'You have killed %tqc of the %tqm Siege Mattekars Borrin asked for.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901322, 13, 1, NULL, 'GotrokSiegeKillTask@KillTaskInProgress');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Keep your voice down. That is the Gotrok forward camp. Linvak Tukal has held against them for longer than I have been alive, and that smith of theirs means to change that.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'The war-beasts are picketed east of the camp. Kill the two Siege Mattekars and the ram goes nowhere. Then come and see me.');
