INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901322, 12, 1, NULL, 'GotrokSiegeKillTask@Proof');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'That is the charge. The gate would not have held. I will see it gets to Tethana, and I will see you are remembered there.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'The quartermaster gave me this for whoever broke the line. It opens something old.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 31, 0, 1, 'GotrokSiegeKillTask');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 22, 0, 1, 'GotrokSiegeWait');
