INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Two of its legion are gone. Now the Herald. It carries a sigil of Aerbax. Bring me the sigil and it cannot sound another raid.');
