INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (901338, 13, 1, NULL, 'UmbralLegionKillTask@KillTaskInProgress');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The shadows are gathering in the east, where the sand turns to rock. The one they call the Herald sounds the raids. I have heard it three nights running.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'It musters its legion east of here, where the A''mun meets the Yushad Ridge, near 14.4S 25.6E. Kill two of its legionaries, and it will come to you.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, amount) VALUES (@e, 2, 70, 0, 1, 'UmbralLegionKillTask', 0);
