INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Aerbax''s ring. Listen to it hum. I will break it on the Tufa anvil at dawn.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'The town put these aside for whoever silenced the Herald. It was a long time coming.');
