INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Three of my sisters are free. The heartwood that bound them breaks with them, mostly. Bring me a binding that did not break.');
