INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'They were keepers of the Deru, like me. Something in the tree''s sickness bound them to it, and now they kill anyone who comes near it.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'I cannot cut the binding. You can. Set three of them free, and bring me the heartwood that held them.');
